"""Triangle-free graphs up to isomorphism, generated by vertex extension.

WHY.  The diagonal S = 0 census runs over supports, and the number of LABELLED
triangle-free graphs explodes -- 5789 at n = 6, 133501 at n = 7, millions at n = 8.
Up to isomorphism the counts are tiny: 38, 107, 410, 1897, 12172 at n = 6..10
(A006785).  Since relabelling coordinates is an O(n) symmetry, one representative
per class is all the census needs.

HOW, WITHOUT nauty OR networkx (neither is installed here).  Build class n from
class n-1: a new vertex may be joined to any INDEPENDENT set of the old graph, and
that is exactly the condition keeping the result triangle-free.  Deduplicate by
bucketing on invariants -- sorted degree sequence, sorted adjacency spectrum,
4-cycle count -- and running an explicit permutation search only inside a bucket,
which stays small.  Cospectral non-isomorphic graphs land in the same bucket and
are separated by the permutation search, so no class is lost.

THE CONTROL.  The class counts must reproduce 1, 2, 3, 7, 14, 38, 107, 410 for
n = 1..8.  A generator that misses classes would silently narrow the census, so the
counts are checked rather than assumed.
"""
import numpy as np, itertools, sys


def _invariant(A):
    n = A.shape[0]
    deg = tuple(sorted(A.sum(1).tolist()))
    ev = tuple(np.round(np.sort(np.linalg.eigvalsh(A)), 8).tolist())
    A2 = A @ A
    c4 = int((np.trace(A2 @ A2) - 2 * A2.sum() + np.trace(A2)) // 8)
    return (n, deg, ev, c4)


def _isomorphic(A, B):
    n = A.shape[0]
    da, db = A.sum(1), B.sum(1)
    if sorted(da.tolist()) != sorted(db.tolist()):
        return False
    order = np.argsort(da)
    cand = [np.flatnonzero(db == da[i]) for i in order]
    perm = [-1] * n
    used = set()

    def rec(k):
        if k == n:
            return True
        for j in cand[k]:
            if j in used:
                continue
            i = order[k]
            ok = True
            for t in range(k):
                if A[i, order[t]] != B[j, perm[t]]:
                    ok = False; break
            if ok:
                perm[k] = j; used.add(j)
                if rec(k + 1):
                    return True
                used.discard(j); perm[k] = -1
        return False

    return rec(0)


def _add(classes, A):
    key = _invariant(A)
    for B in classes.setdefault(key, []):
        if _isomorphic(A, B):
            return False
    classes[key].append(A)
    return True


def triangle_free_classes(nmax):
    """List of representatives per n, from 1 to nmax."""
    out = {1: [np.zeros((1, 1), dtype=int)]}
    for n in range(2, nmax + 1):
        classes = {}
        for A in out[n - 1]:
            m = n - 1
            for bits in range(1 << m):
                nb = [i for i in range(m) if bits >> i & 1]
                if any(A[i, j] for i, j in itertools.combinations(nb, 2)):
                    continue                       # neighbourhood must be independent
                B = np.zeros((n, n), dtype=int)
                B[:m, :m] = A
                for i in nb:
                    B[i, m] = B[m, i] = 1
                _add(classes, B)
        out[n] = [A for v in classes.values() for A in v]
    return out


if __name__ == "__main__":
    nmax = int(sys.argv[1]) if len(sys.argv) > 1 else 8
    known = {1: 1, 2: 2, 3: 3, 4: 7, 5: 14, 6: 38, 7: 107, 8: 410, 9: 1897}
    out = triangle_free_classes(nmax)
    print(f"{'n':>3s} {'classes':>8s} {'A006785':>8s}  agrees")
    for n in range(1, nmax + 1):
        k = known.get(n, "?")
        print(f"{n:3d} {len(out[n]):8d} {str(k):>8s}  "
              f"{'yes' if k == len(out[n]) else ('n/a' if k == '?' else 'NO')}")
